class OpenAIProvider {
  name = "openai";
  client;
  model;
  constructor(config) {
    this.client = new openai_default({
      baseURL: config.baseURL,
      apiKey: config.apiKey
    });
    this.model = config.model;
  }
  isAvailable() {
    return true;
  }
  async review(diffContent, prTitle) {
    const userPrompt = buildUserPrompt(diffContent, prTitle);
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        { role: "user", content: userPrompt }
      ],
      temperature: 0.2,
      max_tokens: 2048,
      response_format: { type: "json_object" }
    });
    const rawContent = response.choices[0]?.message?.content;
    if (!rawContent)
      throw new Error("Empty response from OpenAI");
    const parsed2 = JSON.parse(rawContent);
    const validated = ReviewResultSchema.parse(parsed2);
    logger.info("\u2705 OpenAI review completed", {
      model: this.model,
      commentCount: validated.comments.length
    });
    return { ...validated, comments: validated.comments };
  }
}

// src/ai/providers/anthropic.ts
class AnthropicProvider {
  name = "anthropic";
  apiKey;
  model;
  baseURL;
  constructor(config) {
    this.apiKey = config.apiKey;
    this.model = config.model;
    this.baseURL = config.baseURL ?? "https://api.anthropic.com";
  }
  isAvailable() {
    return true;
  }
  async review(diffContent, prTitle) {
    const userPrompt = buildUserPrompt(diffContent, prTitle);
    const response = await fetch(`${this.baseURL}/v1/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": this.apiKey,
        "anthropic-version": "2023-06-01"
      },
      body: JSON.stringify({
        model: this.model,
        max_tokens: 2048,
        system: SYSTEM_PROMPT,
        messages: [{ role: "user", content: userPrompt }]
      })
    });
    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(`Anthropic API error ${response.status}: ${errorBody}`);
    }
    const data = await response.json();
    const rawContent = data.content?.[0]?.text;
    if (!rawContent)
      throw new Error("Empty response from Anthropic");
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (!jsonMatch)
      throw new Error("No JSON found in Anthropic response");
    const parsed2 = JSON.parse(jsonMatch[0]);
    const validated = ReviewResultSchema.parse(parsed2);
    logger.info("\u2705 Anthropic review completed", {
      model: this.model,
      commentCount: validated.comments.length
    });
    return { ...validated, comments: validated.comments };
  }
}

