class GoogleProvider {
  name = "google";
  apiKey;
  model;
  baseURL;
  constructor(config) {
    this.apiKey = config.apiKey;
    this.model = config.model;
    this.baseURL = config.baseURL ?? "https://generativelanguage.googleapis.com";
  }
  isAvailable() {
    return true;
  }
  async review(diffContent, prTitle) {
    const userPrompt = buildUserPrompt(diffContent, prTitle);
    const fullPrompt = `${SYSTEM_PROMPT}

${userPrompt}`;
    const response = await fetch(`${this.baseURL}/v1beta/models/${this.model}:generateContent?key=${this.apiKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ parts: [{ text: fullPrompt }] }],
        generationConfig: {
          temperature: 0.2,
          maxOutputTokens: 2048
        }
      })
    });
    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(`Google API error ${response.status}: ${errorBody}`);
    }
    const data = await response.json();
    const rawContent = data.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!rawContent)
      throw new Error("Empty response from Google");
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (!jsonMatch)
      throw new Error("No JSON found in Google response");
    const parsed2 = JSON.parse(jsonMatch[0]);
    const validated = ReviewResultSchema.parse(parsed2);
    logger.info("\u2705 Google review completed", {
      model: this.model,
      commentCount: validated.comments.length
    });
    return { ...validated, comments: validated.comments };
  }
}

// src/ai/providers/fallback.ts
class FallbackProvider {
  name = "fallback";
  providers;
  constructor(providers) {
    this.providers = providers.filter((p) => p.isAvailable());
    if (this.providers.length === 0) {
      throw new Error("No AI providers available");
    }
  }
  isAvailable() {
    return this.providers.some((p) => p.isAvailable());
  }
  async review(diffContent, prTitle) {
    let lastError = null;
    for (let i = 0;i < this.providers.length; i++) {
      const provider = this.providers[i];
      try {
        logger.info(`\uD83E\uDD16 Attempting review with ${provider.name}`, {
          attempt: i + 1,
          provider: provider.name
        });
        const result = await provider.review(diffContent, prTitle);
        logger.info(`\u2705 Review succeeded with ${provider.name}`);
        return result;
      } catch (err) {
        lastError = err;
        logger.warn(`\u274C ${provider.name} failed, trying next provider`, {
          error: err.message,
          provider: provider.name
        });
      }
    }
    throw new Error(`All AI providers failed. Last error: ${lastError?.message}`);
  }
}

